Doubly Linked List -> Create a new node.Set its next to point to the current head.Update the previous pointer of the current head (if it exists) to point to the new node.Make the new node the new head.
struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

struct Node* insertAtBeginning(struct Node* head, int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = head;
    newNode->prev = NULL;
    if (head) {
        head->prev = newNode;
    }
    return newNode;
}
Circular Linked List -> Create a new node.If the list is empty, set the new node's next to itself (self-loop).If not, traverse to the last node, update its next to point to the new node, and link the new node's next to the head.Update the head to the new node.
struct Node* insertAtBeginning(struct Node* head, int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    if (!head) {
        newNode->next = newNode;
        return newNode;
    }
    struct Node* temp = head;
    while (temp->next != head) {
        temp = temp->next;
    }
    temp->next = newNode;
    newNode->next = head;
    return newNode;
}
Queue as LinkedList -> Create a new node.Set its next to the current head.Update the head pointer to the new node.
struct Node* insertAtBeginning(struct Node* head, int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = head;
    return newNode;
}

